async function loadDemoSource(
  source: WorkspaceSource,
  ctx: BaseAudioContext,
  signal: AbortSignal,
): Promise<AudioBuffer> {
  const url = demoUrls[source.id];
  if (url) {
    const response = await fetch(url, { credentials: 'omit', signal });
    if (!response.ok) {
      throw new Error(`ßâñßâÉßâÿßâÜßâÿ ßâòßâößâá ßâ⌐ßâÉßâÿßâóßâòßâÿßâáßâùßâÉ (${response.status})`);
    }
    return ctx.decodeAudioData(await response.arrayBuffer());
  }
  const generate = demoSynths[source.id];
  if (!generate) {
    throw new Error('ßâúßâ¬ßâ£ßâ¥ßâæßâÿ ßâôßâößâ¢ßâ¥ ßâ¼ßâºßâÉßâáßâ¥');
  }
  const channels = generateDemoStereoChannels(generate);
  const buffer = new AudioBuffer({
    numberOfChannels: channels.length,
    length: channels[0].length,
    sampleRate: DEMO_SYNTH_SAMPLE_RATE,
  });
  channels.forEach((channel, index) => buffer.copyToChannel(channel, index));
  return buffer;
}

