export function ArrangementProvider({
  collection,
  initialArrangement,
  children,
}: ArrangementProviderProps) {
  const [history, setHistory] = useState<ArrangementHistory>(() =>
    createHistory(initialArrangement ?? fallbackArrangement()),
  );
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [selectedSourceId, setSelectedSourceId] = useState<string | null>(
    collection.sources[0]?.id ?? null,
  );
  const [range, setRange] = useState<TimeRange | null>(null);
  const [activeTrackId, setActiveTrackId] = useState<string | null>(
    () =>
      (initialArrangement ?? history.present).tracks.find((track) => track.kind === 'audio')?.id ??
      null,
  );
  const [position, setPosition] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [pxPerSecond, setPxPerSecondState] = useState(DEFAULT_PX_PER_SECOND);
  const [status, setStatus] = useState('ßâôßâößâ¢ßâ¥ ßâÖßâ¥ßâÜßâößâÑßâ¬ßâÿßâÉ ßâÿßâóßâòßâÿßâáßâùßâößâæßâÉΓÇª');
  const [sourceStates, setSourceStates] = useState<Record<string, SourceLoadState>>({});
  const [sourcePeaks, setSourcePeaks] = useState<ReadonlyMap<string, Float32Array>>(new Map());
  const [exportState, setExportState] = useState<ArrangementExportState>({
    phase: 'idle',
    message: null,
  });

  const historyRef = useRef(history);
  const positionRef = useRef(0);
  const isPlayingRef = useRef(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const buffersRef = useRef(new Map<string, AudioBuffer>());
  const handleRef = useRef<ScheduleHandle | null>(null);
  const retiredRef = useRef<RetiredGraph[]>([]);
  const anchorRef = useRef({ ctxTime: 0, position: 0 });
  const scheduledKeyRef = useRef('');
  const frameRef = useRef<number | null>(null);
  const volumeBeforeRef = useRef<Arrangement | null>(null);
  const latestRef = useRef({ selectedClipId, selectedSourceId, range, activeTrackId, sourceStates });
  latestRef.current = { selectedClipId, selectedSourceId, range, activeTrackId, sourceStates };

  const updateHistory = useCallback((next: ArrangementHistory) => {
    historyRef.current = next;
    setHistory(next);
  }, []);

  const updatePosition = useCallback((next: number) => {
    positionRef.current = next;
    setPosition(next);
  }, []);

  const livePosition = useCallback((): number => {
    const ctx = audioContextRef.current;
    if (!isPlayingRef.current || !ctx) {
      return positionRef.current;
    }
    const anchor = anchorRef.current;
    return Math.max(0, anchor.position + (ctx.currentTime - anchor.ctxTime));
  }, []);

  const releaseRetiredGraphs = useCallback((all: boolean) => {
    const now = audioContextRef.current?.currentTime ?? 0;
    retiredRef.current = retiredRef.current.filter((entry) => {
      if (all || entry.stopAt + RETIRED_GRAPH_GRACE < now) {
        entry.handle.disconnect();
        return false;
      }
      return true;
    });
  }, []);

  const stopGraph = useCallback(() => {
    if (handleRef.current) {
      handleRef.current.stop();
      handleRef.current.disconnect();
      handleRef.current = null;
    }
    for (const entry of retiredRef.current) {
      entry.handle.stop();
    }
    releaseRetiredGraphs(true);
  }, [releaseRetiredGraphs]);

  const startGraph = useCallback(
    (arrangement: Arrangement, from: number, startAt: number) => {
      const ctx = audioContextRef.current;
      if (!ctx) {
        return;
      }
      const handle = applySchedule(ctx, planSchedule(arrangement, from), {
        buffers: buffersRef.current,
        tracks: arrangement.tracks,
        from,
        startAt,
      });
      const previous = handleRef.current;
      if (previous) {
        previous.stop(startAt);
        retiredRef.current.push({ handle: previous, stopAt: startAt });
      }
      handleRef.current = handle;
      anchorRef.current = { ctxTime: startAt, position: from };
      scheduledKeyRef.current = clipsKey(arrangement);
      releaseRetiredGraphs(false);
    },
    [releaseRetiredGraphs],
  );

  const stopPlayback = useCallback(
    (at?: number) => {
      const stoppedAt = at ?? livePosition();
      stopGraph();
      isPlayingRef.current = false;
      setIsPlaying(false);
      if (frameRef.current !== null) {
        cancelAnimationFrame(frameRef.current);
        frameRef.current = null;
      }
      updatePosition(stoppedAt);
    },
    [livePosition, stopGraph, updatePosition],
  );

  const tick = useCallback(() => {
    if (!isPlayingRef.current) {
      frameRef.current = null;
      return;
    }
    const end = projectEnd(historyRef.current.present);
    const current = livePosition();
    if (current >= end) {
      stopPlayback(end);
      return;
    }
    updatePosition(current);
    releaseRetiredGraphs(false);
    frameRef.current = requestAnimationFrame(tick);
  }, [livePosition, releaseRetiredGraphs, stopPlayback, updatePosition]);

  const syncPlayback = useCallback(
    (arrangement: Arrangement, removed?: { a: number; b: number }) => {
      const ctx = audioContextRef.current;
      if (!isPlayingRef.current || !ctx) {
        return;
      }
      if (removed || clipsKey(arrangement) !== scheduledKeyRef.current) {
        const startAt = ctx.currentTime + PLAYBACK_LOOKAHEAD;
        const anchor = anchorRef.current;
        const handoff = Math.max(0, anchor.position + (startAt - anchor.ctxTime));
        const from = removed ? remapTime(handoff, removed.a, removed.b) : handoff;
        startGraph(arrangement, from, startAt);
        return;
      }
      const handle = handleRef.current;
      if (!handle) {
        return;
      }
      for (const track of arrangement.tracks) {
        if (track.kind === 'audio') {
          handle.setTrackGain(
            track.id,
            isTrackAudible(track, arrangement.tracks) ? track.volume : 0,
          );
        }
      }
    },
    [startGraph],
  );

  const applyEdit = useCallback(
    (
      next: Arrangement,
      label: string,
      before?: Arrangement,
      removed?: { a: number; b: number },
    ): boolean => {
      const current = historyRef.current;
      const committed = commitHistory(current, next, label, before);
      if (committed === current) {
        return false;
      }
      updateHistory(committed);
      syncPlayback(committed.present, removed);
      return committed.past.length !== current.past.length;
    },
    [syncPlayback, updateHistory],
  );

  const ensureAudioContext = useCallback((): AudioContext => {
    let ctx = audioContextRef.current;
    if (!ctx) {
      ctx = new AudioContext({ latencyHint: 'interactive' });
      audioContextRef.current = ctx;
    }
    if (ctx.state === 'suspended') {
      void ctx.resume();
    }
    return ctx;
  }, []);

