    if (isPlayingRef.current) {
      stopPlayback();
      return;
    }
    const arrangement = historyRef.current.present;
    const end = projectEnd(arrangement);
    if (end <= 0) {
      setStatus('ßâôßâÉßâíßâÉßâÖßâáßâÉßâòßâÿ ßâÉßâáßâÉßâñßâößâáßâÿßâÉ ΓÇö ßâ»ßâößâá ßâæßâÿßâæßâÜßâÿßâ¥ßâùßâößâÖßâÿßâôßâÉßâ£ ßâôßâÉßâÉßâ¢ßâÉßâóßâö ßâÖßâÜßâÿßâ₧ßâÿ.');
      return;
    }
    const ctx = ensureAudioContext();
    const from = positionRef.current >= end - ARRANGEMENT_EPS ? 0 : positionRef.current;
    isPlayingRef.current = true;
    setIsPlaying(true);
    updatePosition(from);
    startGraph(arrangement, from, ctx.currentTime + PLAYBACK_LOOKAHEAD);
    if (frameRef.current === null) {
      frameRef.current = requestAnimationFrame(tick);
    }
  }, [ensureAudioContext, startGraph, stopPlayback, tick, updatePosition]);

  const seekTo = useCallback(
    (time: number) => {
      const target = Math.max(0, time);
