      if (!track || track.kind !== 'audio') {
        setStatus('ßâÉßâÿßâáßâ⌐ßâÿßâö ßâÉßâúßâôßâÿßâ¥ ßâ«ßâÉßâûßâÿ (ßâ¢ßâúßâíßâÿßâÖßâÉ, ßâíßâóßâößâ¢ßâößâæßâÿ ßâÉßâ£ SFX) ΓÇö ßâòßâÿßâôßâößâ¥ßâ«ßâÉßâûßâûßâö ßâÉßâúßâôßâÿßâ¥ ßâÉßâá ßâößâ¢ßâÉßâóßâößâæßâÉ.');
